AS BEGIN SET NOCOUNT ON; ;WITH Ranked AS ( SELECT e.[Id], e.[PublicId], e.[Status], CONVERT(VARCHAR(19), e.[ExpenseDate], 120) AS [ExpenseDate], e.[TotalAmount], e.[ReferenceNumber], p.[RealmId], p.[QboId] AS [PurchaseQboId], pl.[QboLineId], pl.[Id] AS [QboPurchaseLineId], cs.[PublicId] AS [CodingItemPublicId], ROW_NUMBER() OVER (PARTITION BY e.[Id] ORDER BY eli.[Id], pl.[Id]) AS [Rn] FROM dbo.[Expense] e INNER JOIN dbo.[ExpenseLineItem] eli ON eli.[ExpenseId] = e.[Id] INNER JOIN qbo.[Purchase] p ON p.[QboId] = e.[QboId] AND p.[RealmId] = e.[RealmId] INNER JOIN qbo.[PurchaseLine] pl ON pl.[QboPurchaseId] = p.[Id] AND pl.[QboLineId] = eli.[QboId] AND eli.[RealmId] = p.[RealmId] LEFT JOIN dbo.[CodingSuggestion] cs ON cs.[TargetKind] = N'expense' AND cs.[RealmId] = p.[RealmId] AND cs.[QboPurchaseQboId] = p.[QboId] AND (cs.[ExpenseId] = e.[Id] OR cs.[ExpenseId] IS NULL) WHERE e.[Status] = N'completed' AND e.[StatusOrigin] = N'qbo_pull' AND pl.[AccountRefName] LIKE N'%NEED TO CATEGORIZE%' AND pl.[ItemRefValue] IS NULL ) SELECT [Id], [PublicId], [Status], [ExpenseDate], [TotalAmount], [ReferenceNumber], [RealmId], [PurchaseQboId], [QboLineId], [QboPurchaseLineId], [CodingItemPublicId] FROM Ranked WHERE [Rn] = 1; END;
